import { Accessor, createContext, createSignal, Setter, useContext } from "solid-js";
import { createMutable } from "solid-js/store";

import ContextManager from "#core/ui/context-manager/context-manager.js";

import { getQuestTracker } from "#base/ui/quest-tracker/quest-tracker.js";
import { getLegacyCardStyling } from "#base/ui-next/screens/legacies/legacies-support.js";

export interface TriumphData {
	triumphName: string;
	triumphRequirements: string;
	triumphDescription: string;
	isTriggered: boolean;
	isFirstOnly: boolean;
	progressString: string;
	currentProgress: number;
	progressGoal: number;
	lockedReason?: string;
	traitIcon: string;
	bgColor: string;
	descriptionBG: string;
	raceWinnerName?: string;
	isComingSoon: boolean;
	triumphType: string;
	isTracked: boolean;
	isMajor: boolean;
	progressPips?: number[];
	filterOptions: string[];
}

interface TriumphTabData {
	titleText: string;
	triumphs: TriumphData[];
}

export interface LegacyScreenContextModel {
	triumphSections: TriumphTabData[];
	playerColor: string;
	bgSrc: string;
	onClickClose: () => void;
	selectedTriumphFilter: Accessor<TriumphFilterOptions | undefined>;
	setSelectedTriumphFilter: Setter<TriumphFilterOptions | undefined>;
	isShowingDetails: Accessor<boolean>;
	setIsShowingDetails: Setter<boolean>;
}

export enum TriumphFilterOptions {
	DEFAULT = "DEFAULT",
	CULTURAL = "CULTURAL",
	DIPLOMATIC = "DIPLOMATIC",
	ECONOMIC = "ECONOMIC",
	EXPANSIONIST = "EXPANSIONIST",
	MILITARISTIC = "MILITARISTIC",
	SCIENTIFIC = "SCIENTIFIC",
	CRISIS = "CRISIS",
	IN_PROGRESS = "IN_PROGRESS",
	COMPLETE = "COMPLETE",
	INCOMPLETE = "INCOMPLETE",
	FIRST_ONLY = "FIRST_ONLY",
	TRACKED = "TRACKED",
	UNTRACKED = "UNTRACKED",
}

export enum CivFilterOptions {
	ALL_ATTRIBUTES = "LOC_LEGACIES_FILTER_ALL_ATTRIBUTES",
	CULTURAL = "LOC_TAG_TRAIT_CULTURAL_NAME",
	ECONOMIC = "LOC_TAG_TRAIT_ECONOMIC_NAME",
	SCIENTIFIC = "LOC_TAG_TRAIT_EXPANSIONIST_NAME",
	MILITARISTIC = "LOC_TAG_TRAIT_MILITARISTIC_NAME",
	EXPANSIONIST = "LOC_TAG_TRAIT_POLITICAL_NAME",
	DIPLOMATIC = "LOC_TAG_TRAIT_SCIENTIFIC_NAME",
	WILDCARD = "LOC_TAG_TRAIT_WILDCARD_NAME",
}

// Triumphs were formerly called legacies, legacy now refers to the overall system (unlocks, triumphs, and dedications).
// GameCore definitions still refer to individual triumphs as legacies.
export function createTriumphData(triumphDef: LegacyDefinition): TriumphData {
	const playerLegacies = Players.get(GameContext.localPlayerID)?.Legacies;
	const questTracker = getQuestTracker();
	if (!playerLegacies) {
		console.error("legacies-model: Unable to get legacies object for local player while creating the legacy car");
		return {
			triumphName: "",
			isTriggered: false,
			lockedReason: "",
			progressString: "",
			triumphRequirements: triumphDef.TriggerDescription,
			triumphDescription: triumphDef.Description,
			isFirstOnly: false,
			traitIcon: "",
			bgColor: "",
			descriptionBG: "",
			isComingSoon: false,
			triumphType: triumphDef.LegacyType,
			isTracked: questTracker.has(triumphDef.LegacyType, "triumph"),
			isMajor: triumphDef.MajorLegacy,
			filterOptions: [],
			progressGoal: 0,
			currentProgress: 0,
		};
	}

	let lockedReason: string | undefined;
	for (const id of Players.getWasEverAliveMajorIds()) {
		if (id == GameContext.localPlayerID) {
			break;
		}
		const player = Players.get(Players.getWasEverAliveMajorIds()[id]);
		if (triumphDef.FirstPlayerOnly && player?.Legacies?.isTriggered(triumphDef.LegacyType)) {
			lockedReason = Locale.compose("LOC_LEGACIES_ALREADY_EARNED_BY", player.name);
			break;
		}
	}

	const filterOptions = [];
	const triumphProgress = playerLegacies.getProgress(triumphDef.LegacyType);
	const isTriggered = playerLegacies.isTriggered(triumphDef.LegacyType) ?? false;
	let progressString: string | undefined = undefined;
	let currentProgress: number | undefined = undefined;
	let progressGoal: number | undefined = undefined;

	if (triumphProgress) {
		progressString = triumphProgress.progress[0].current + "/" + triumphProgress.progress[0].total;
		currentProgress = triumphProgress.progress[0].current;
		progressGoal = triumphProgress.progress[0].total;

		if (triumphProgress.progress[0].current > 0 && !isTriggered) {
			filterOptions.push(TriumphFilterOptions.IN_PROGRESS);
		}
	}

	if (isTriggered) {
		filterOptions.push(TriumphFilterOptions.COMPLETE);
	} else {
		if (!(triumphProgress?.raceWinner != GameContext.localPlayerID && triumphProgress?.raceWinner != -1)) {
			filterOptions.push(TriumphFilterOptions.INCOMPLETE);
		}
	}

	if (triumphDef.FirstPlayerOnly) {
		filterOptions.push(TriumphFilterOptions.FIRST_ONLY);
	}

	const { tagType, traitIcon, bgColor, comingSoon, descriptionBG } = getLegacyCardStyling(triumphDef.LegacyType);

	filterOptions.push(tagType);
	filterOptions.push(TriumphFilterOptions.DEFAULT);

	const legacyData: TriumphData = {
		triumphName: Locale.compose(triumphDef.Name),
		isTriggered: isTriggered,
		lockedReason: lockedReason,
		progressString: progressString ?? "",
		currentProgress: currentProgress ?? 0,
		progressGoal: progressGoal ?? 0,
		triumphRequirements: triumphDef.TriggerDescription,
		triumphDescription: triumphDef.Description,
		isFirstOnly:
			triumphDef.FirstPlayerOnly &&
			triumphProgress?.raceWinner != GameContext.localPlayerID &&
			triumphProgress?.raceWinner != -1,
		traitIcon: traitIcon,
		bgColor: bgColor,
		descriptionBG: descriptionBG,
		isComingSoon: comingSoon,
		triumphType: triumphDef.LegacyType,
		isTracked: questTracker.has(triumphDef.LegacyType, "triumph"),
		isMajor: triumphDef.MajorLegacy,
		filterOptions: filterOptions,
	};

	if (progressGoal && progressGoal <= 10) {
		const progressPips: number[] = [];
		for (let i = 1; i <= progressGoal; i++) {
			progressPips.push(i);
		}
		legacyData.progressPips = progressPips;
	}

	if (triumphProgress && triumphProgress?.raceWinner != -1) {
		const localPlayerDiplomacy = Players.get(GameContext.localPlayerID)?.Diplomacy;
		const playerName = localPlayerDiplomacy?.hasMet(triumphProgress?.raceWinner)
			? Players.get(triumphProgress?.raceWinner)?.name
			: Locale.compose("LOC_UI_UNMET_PLAYER_NAME");
		if (playerName) {
			legacyData.raceWinnerName = playerName;
		}
	}
	return legacyData;
}

function populateTriumphData(): TriumphTabData[] {
	let allTriumphData: TriumphTabData[] = [];
	const majorTriumphsSection: TriumphTabData = {
		titleText: "LOC_LEGACIES_MAJOR_TRIUMPHS",
		triumphs: [],
	};
	const minorTriumphsSection: TriumphTabData = {
		titleText: "LOC_LEGACIES_MINOR_TRIUMPHS",
		triumphs: [],
	};

	const playerLegacies = Players.get(GameContext.localPlayerID)?.Legacies;
	if (!playerLegacies) {
		return allTriumphData;
	}

	GameInfo.Legacies.forEach((triumph) => {
		if (!playerLegacies.isValidLegacy(triumph.LegacyType)) {
			return;
		}

		const triumphData = createTriumphData(triumph);

		if (triumph.MajorLegacy) {
			majorTriumphsSection.triumphs.push(triumphData);
		} else {
			minorTriumphsSection.triumphs.push(triumphData);
		}
	});

	allTriumphData = [majorTriumphsSection, minorTriumphsSection];

	return allTriumphData;
}

export function createLegaciesScreenModel() {
	const [selectedTriumphFilter, setSelectedTriumphFilter] = createSignal<TriumphFilterOptions | undefined>(
		TriumphFilterOptions.DEFAULT,
	);

	function handleClickClose() {
		ContextManager.pop("screen-legacies");
	}

	let bgSrc = "";
	let playerColor = "";

	const localPlayer = Players.get(GameContext.localPlayerID);
	if (localPlayer != null) {
		const civDefinition = GameInfo.Civilizations.lookup(localPlayer.civilizationType);
		if (civDefinition) {
			const civInfo = GameInfo.LoadingInfo_Civilizations.lookup(civDefinition?.CivilizationType);

			const civImagePath: string | undefined =
				window.innerWidth >= 1080 ? civInfo?.BackgroundImageHigh : civInfo?.BackgroundImageLow;
			const civImage = civImagePath ? `url(${civImagePath})` : "";
			bgSrc = civImage;
		}

		const bgColor = UI.Color.getPlayerColors(GameContext.localPlayerID);

		if (bgColor) {
			const variants = UI.Color.createPlayerColorVariants(bgColor);
			playerColor = variants.primaryColor.tintColor;
		}
	}

	const [isShowingDetails, setIsShowingDetails] = createSignal<boolean>(false);

	const model = createMutable<LegacyScreenContextModel>({
		triumphSections: populateTriumphData(),
		onClickClose: handleClickClose,
		selectedTriumphFilter,
		setSelectedTriumphFilter,
		playerColor,
		bgSrc,
		isShowingDetails,
		setIsShowingDetails,
	});
	//#endregion

	return model;
}

export const LegaciesScreenContext = createContext<LegacyScreenContextModel>();

export function useLegaciesScreenContext() {
	const context = useContext(LegaciesScreenContext);

	if (!context) {
		throw new Error("Unable to get legacies screen context!");
	}

	return context;
}
